using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Cysharp.Threading.Tasks;
using Game.Access;
using MiniFramework.Contracts;
using MiniFramework.Storage;
using MiniFramework.Ads;
using MiniFramework.Providers.StorageFake;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
using ReviveTests;
public sealed class ReviveServiceTests
{
    sealed class LoginOwner:MiniFramework.Contracts.IModule,MiniFramework.Contracts.IClaimOwnerAuthority
    {
        public readonly MiniFramework.Accounts.AccountService Inner;public string Id=>"owner";public IReadOnlyList<string> Dependencies {get;}public ClaimOwnerMode Mode=>ClaimOwnerMode.AccountScoped;public ClaimOwnerSnapshot? CurrentOwner=>Inner.CurrentOwner;
        public LoginOwner(MiniFramework.Providers.IdentityFake.FakeIdentityProvider identity,string store){Inner=new MiniFramework.Accounts.AccountService(MiniFramework.Ownership.OwnershipPolicy.AccountScoped(true),new MiniFramework.Ownership.OwnerGenerationSequence(),identity,id:Id);Dependencies=new[]{store};}
        public async UniTask<Result> InitializeAsync(IModuleContext context,OperationContext wait){var r=await Inner.InitializeAsync(context,wait);if(!r.IsSuccess)return r;var c=await Inner.CaptureSwitch().Value.WaitAsync(wait);return c.IsSuccess?Result.Success():Result.Failure(c.Error);}
        public Result ValidateCurrent(ClaimOwnerSnapshot o)=>Inner.ValidateCurrent(o);public Result<StorageAddress> AddressForCurrent(string slot)=>Inner.AddressForCurrent(slot);
        public UniTask<Result> StopAsync(CleanupContext c)=>Inner.StopAsync(c);public UniTask<Result> DisposeAsync(CleanupContext c)=>Inner.DisposeAsync(c);
    }
    readonly List<Env> envs=new List<Env>();Env New(FakeStorageStore disk=null,AdReceiptJournal facts=null,bool switchOwner=false){var e=new Env(disk,facts,switchingOwner:switchOwner);envs.Add(e);return e;}
    [UnityTearDown] public IEnumerator Teardown()=>UniTask.ToCoroutine(async()=>{Time.timeScale=1;foreach(var e in envs)await e.Finish();envs.Clear();});
    static FrameworkError Error(string code,ErrorKind kind=ErrorKind.Storage)=>new FrameworkError(kind,code);
    static AdPresentationReceipt Receipt(ReviveClaim c,AdWatchOutcome outcome=AdWatchOutcome.Completed,ClaimOwnerSnapshot? owner=null,string attempt=null,PlatformExecutionMode mode=PlatformExecutionMode.Mock)=>new AdPresentationReceipt(attempt??c.AttemptId,new RewardedAdRequest("revive",c.ClaimId,owner??c.Owner,true),mode,outcome,true);
    [UnityTest] public IEnumerator StartupReservesGenerationBeforePublishingOwner()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(1,e.Storage.Writes);Assert.AreEqual(1,e.ReadRaw().LastGeneration);Assert.AreEqual(1,e.Owner.CurrentOwner.Value.SessionGeneration);});
    [UnityTest] public IEnumerator ReviveRequiresFailedRun()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.IsFalse(e.Service.CaptureRevive().IsSuccess);Env.Check(await e.Service.BeginRunAsync(1,Env.Wait));Assert.IsFalse(e.Service.CaptureRevive().IsSuccess);Env.Check(await e.Service.FailRunAsync(Env.Wait));Assert.IsTrue(e.Service.CanRevive);});
    [UnityTest] public IEnumerator CaptureIsColdAndWaitIsSingleUse()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var before=e.Storage.Writes;var op=e.Capture();Assert.AreEqual(before,e.Storage.Writes);Assert.AreEqual(0,e.Backend.Attempts.Count);Assert.IsTrue((await op.WaitAsync(Env.Wait)).IsSuccess);Assert.IsFalse((await op.WaitAsync(Env.Wait)).IsSuccess);});
    [UnityTest] public IEnumerator CompleteCommitsRewardMarkerAndProgressTogether()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var op=e.Capture();var r=await op.WaitAsync(Env.Wait);Assert.IsTrue(r.IsSuccess&&r.Value.Granted);var raw=e.ReadRaw();Assert.AreEqual(5,raw.Coins);Assert.AreEqual(ReviveRunPhase.Playing,raw.Phase);Assert.IsTrue(raw.ReviveUsed);Assert.AreEqual(op.AttemptId,raw.Claims.Single().AttemptId);Assert.AreEqual(ReviveClaimState.Granted,raw.Claims.Single().State);Assert.AreEqual(e.Store.Sequence,raw.Claims.Single().GrantSequence);});
    [UnityTest] public IEnumerator VolatileCommitNeverClaimsDurability()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var r=await e.Capture().WaitAsync(Env.Wait);Assert.IsTrue(r.IsSuccess);Assert.IsFalse(r.Value.IsDurable);Assert.AreEqual(StoragePersistence.Volatile,r.Value.Commit.Receipt.Persistence);});
    [UnityTest] public IEnumerator IntentMustCommitBeforeNativeLoad()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();e.Storage.HoldNext=true;var task=e.Capture().WaitAsync(Env.Wait);await Env.Frames();Assert.AreEqual(0,e.Backend.Attempts.Count);Assert.IsNull(e.Store.Snapshot.Pending);e.Storage.Release();Assert.IsTrue((await task).IsSuccess);Assert.AreEqual(1,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator IntentRejectionNeverStartsAdvertisement()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var before=e.Disk.CopyRaw(Env.Address);e.Disk.Faults.Enqueue(FakeStorageFault.Reject);Assert.IsFalse((await e.Capture().WaitAsync(Env.Wait)).IsSuccess);Assert.AreEqual(0,e.Backend.Attempts.Count);CollectionAssert.AreEqual(before,e.Disk.CopyRaw(Env.Address));Assert.IsTrue(e.Service.CanRevive);});
    [UnityTest] public IEnumerator UnknownIntentNeverStartsAdAndRequiresReopen()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();e.Disk.Faults.Enqueue(FakeStorageFault.UnknownAfterWrite);Assert.IsFalse((await e.Capture().WaitAsync(Env.Wait)).IsSuccess);Assert.AreEqual(0,e.Backend.Attempts.Count);Assert.IsTrue(e.Store.RecoveryRequired);Assert.IsFalse(e.Service.CaptureRevive().IsSuccess);Assert.IsNotNull(e.ReadRaw().Pending);});
    [UnityTest] public IEnumerator TenDuplicateCompletedFactsNeverDoubleGrant()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var r=(await e.Capture().WaitAsync(Env.Wait)).Value;var writes=e.Storage.Writes;for(var i=0;i<10;i++)Env.Check(e.Service.Record(r.Presentation));Assert.AreEqual(5,e.Store.Snapshot.Coins);Assert.AreEqual(writes,e.Storage.Writes);Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.AreEqual(0,e.Facts.PendingCount);});
    [UnityTest] public IEnumerator SameRunReviveLimitSurvivesSecondFailure()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();await e.Capture().WaitAsync(Env.Wait);Env.Check(await e.Service.FailRunAsync(Env.Wait));Assert.IsFalse(e.Service.CanRevive);Assert.IsFalse(e.Service.CaptureRevive().IsSuccess);Assert.AreEqual(1,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator NewRunCanReviveWithoutReplayingPriorClaim()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();await e.Capture().WaitAsync(Env.Wait);var old=e.Store.Snapshot.RunId;await e.FailedRun();Assert.AreNotEqual(old,e.Store.Snapshot.RunId);await e.Capture().WaitAsync(Env.Wait);Assert.AreEqual(10,e.Store.Snapshot.Coins);Assert.AreEqual(2,e.Store.Snapshot.Claims.Count);});
    [UnityTest] public IEnumerator SkipEndsIntentWithoutReward()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Skip=true;await e.Start();await e.FailedRun();var r=await e.Capture().WaitAsync(Env.Wait);Assert.IsTrue(r.IsSuccess);Assert.IsFalse(r.Value.Granted);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.AreEqual(ReviveClaimState.Aborted,e.Store.Snapshot.Claims.Single().State);Assert.IsTrue(e.Service.CanRevive);});
    [UnityTest] public IEnumerator NoFillPreservesErrorAndDoesNotGrant()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.LoadError=Error("test.nofill",ErrorKind.NoFill);await e.Start();await e.FailedRun();var r=await e.Capture().WaitAsync(Env.Wait);Assert.AreEqual(ErrorKind.NoFill,r.Error.Kind);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.AreEqual(0,e.Attempt.ShowCount);Assert.IsNull(e.Store.Snapshot.Pending);});
    [UnityTest] public IEnumerator PreCanceledWaitWritesNoIntent()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var writes=e.Storage.Writes;using(var c=new CancellationTokenSource()){c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Capture().WaitAsync(OperationContext.Unlimited(c.Token))).Error.Kind);}Assert.AreEqual(writes,e.Storage.Writes);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ZeroBudgetWritesNoIntent()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var writes=e.Storage.Writes;Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(default)).Error.Kind);Assert.AreEqual(writes,e.Storage.Writes);});
    [UnityTest] public IEnumerator CancelDuringIntentWriteWaitsAndPreventsShow()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();e.Storage.HoldNext=true;using(var c=new CancellationTokenSource()){var t=e.Capture().WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.IsTrue(e.Service.Busy);e.Storage.Release();await Env.Frames(10);Assert.AreEqual(0,e.Backend.Attempts.Count);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.IsNull(e.Store.Snapshot.Pending);Assert.IsFalse(e.Service.Busy);}});
    [UnityTest] public IEnumerator CancelDuringLoadKeepsActualOwnershipAndAbortsClaim()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldLoad=true;await e.Start();await e.FailedRun();using(var c=new CancellationTokenSource()){var t=e.Capture().WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();await t;Assert.AreEqual(1,e.Ads.ActiveAttemptCount);Assert.IsTrue(e.Service.Busy);e.Attempt.CompleteLoad();await Env.Frames(10);Assert.AreEqual(0,e.Attempt.ShowCount);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.AreEqual(ReviveClaimState.Aborted,e.Store.Snapshot.Claims.Single().State);}});
    [UnityTest] public IEnumerator ViewCloseDoesNotDropLateGrantCleanup()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var view=new MiniFramework.Runtime.Scope("view");var op=e.Capture();var t=op.WaitAsync(OperationContext.Unlimited(view.LifetimeCancellation));await view.CloseAsync(Env.Cleanup);Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Attempt.CompleteShow();await Env.Frames(10);Assert.AreEqual(5,e.Store.Snapshot.Coins);Assert.AreEqual(ReviveOperationPhase.Completed,op.Phase);Assert.AreEqual(1,e.Attempt.CleanupCount);});
    [UnityTest] public IEnumerator TimeoutObservationDoesNotRevokeMatchedCompletedFact()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var op=e.Capture();Assert.AreEqual(ErrorKind.Timeout,(await op.WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);e.Attempt.CompleteShow();await Env.Frames(10);Assert.AreEqual(5,e.Store.Snapshot.Coins);Assert.AreEqual(ReviveOperationPhase.Completed,op.Phase);});
    [UnityTest] public IEnumerator GrantRejectionKeepsReceiptForExplicitCommitOnlyRetry()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);e.Disk.Faults.Enqueue(FakeStorageFault.Reject);e.Attempt.CompleteShow();Assert.IsFalse((await t).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.IsNotNull(e.Store.Snapshot.Pending);Assert.AreEqual(1,e.Facts.PendingCount);var recovered=await e.Service.RecoverPendingAsync(Env.Wait);Assert.IsTrue(recovered.IsSuccess&&recovered.Value.Granted);Assert.AreEqual(5,e.Store.Snapshot.Coins);Assert.AreEqual(1,e.Backend.Attempts.Count);Assert.AreEqual(0,e.Facts.PendingCount);});
    [UnityTest] public IEnumerator UnknownAfterGrantReopensAlreadyGrantedExactlyOnce()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);e.Disk.Faults.Enqueue(FakeStorageFault.UnknownAfterWrite);e.Attempt.CompleteShow();Assert.IsFalse((await t).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.AreEqual(5,e.ReadRaw().Coins);Assert.IsFalse((await e.Service.RecoverPendingAsync(Env.Wait)).IsSuccess);Env.Check(await e.Context.CloseAsync(Env.Wait));var n=New(e.Disk,e.Facts);await n.Start();Assert.AreEqual(5,n.Store.Snapshot.Coins);Assert.IsNull(n.Store.Snapshot.Pending);Assert.AreEqual(0,n.Backend.Attempts.Count);Assert.AreEqual(0,n.Facts.PendingCount);});
    [UnityTest] public IEnumerator UnknownBeforeGrantReopenNeedsExplicitOriginalFactRecovery()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);e.Disk.Faults.Enqueue(FakeStorageFault.UnknownBeforeWrite);e.Attempt.CompleteShow();await t;Env.Check(await e.Context.CloseAsync(Env.Wait));var n=New(e.Disk,e.Facts);await n.Start();Assert.AreEqual(0,n.Store.Snapshot.Coins);Assert.IsNotNull(n.Store.Snapshot.Pending);Assert.IsTrue((await n.Service.RecoverPendingAsync(Env.Wait)).Value.Granted);Assert.AreEqual(5,n.Store.Snapshot.Coins);Assert.AreEqual(0,n.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ExceptionAfterWriteRequiresReadReconciliation()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);e.Disk.Faults.Enqueue(FakeStorageFault.ExceptionAfterWrite);e.Attempt.CompleteShow();Assert.IsFalse((await t).IsSuccess);Assert.IsTrue(e.Store.RecoveryRequired);Env.Check(await e.Context.CloseAsync(Env.Wait));var n=New(e.Disk,e.Facts);await n.Start();Assert.AreEqual(5,n.Store.Snapshot.Coins);Assert.AreEqual(1,n.Store.Snapshot.Claims.Count);});
    [UnityTest] public IEnumerator LostProofNeverCreatesRewardAndCanBeExplicitlyAbandoned()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();e.Disk.Faults.Enqueue(FakeStorageFault.UnknownAfterWrite);await e.Capture().WaitAsync(Env.Wait);Env.Check(await e.Context.CloseAsync(Env.Wait));var n=New(e.Disk,new AdReceiptJournal());await n.Start();Assert.IsNotNull(n.Store.Snapshot.Pending);Assert.IsFalse((await n.Service.RecoverPendingAsync(Env.Wait)).IsSuccess);Env.Check(await n.Service.AbandonPendingAsync(Env.Wait));Assert.AreEqual(0,n.Store.Snapshot.Coins);Assert.AreEqual(ReviveClaimState.Aborted,n.Store.Snapshot.Claims.Single().State);Assert.IsTrue(n.Service.CanRevive);Assert.AreEqual(0,n.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator KnownCompletionCannotBeDiscardedAsUnproven()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);e.Disk.Faults.Enqueue(FakeStorageFault.Reject);e.Attempt.CompleteShow();await t;Assert.IsFalse((await e.Service.AbandonPendingAsync(Env.Wait)).IsSuccess);Assert.IsTrue((await e.Service.RecoverPendingAsync(Env.Wait)).Value.Granted);});
    [UnityTest] public IEnumerator FullJournalRetainsCompletionAndBlocksUnprovenAbandon()=>UniTask.ToCoroutine(async()=>
    {
        var facts=new AdReceiptJournal(1);var other=new AdPresentationReceipt("unrelated-attempt",new RewardedAdRequest("other","unrelated-claim",new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,Env.OwnerId,1,Env.Ns),true),PlatformExecutionMode.Mock,AdWatchOutcome.Completed,true);Env.Check(facts.Record(other));
        var e=New(facts:facts);await e.Start();await e.FailedRun();Assert.IsFalse((await e.Capture().WaitAsync(Env.Wait)).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.IsNotNull(e.Store.Snapshot.Pending);Assert.Greater(e.Ads.ReadDiagnostics().FailedCleanup,0);
        Assert.IsFalse((await e.Service.AbandonPendingAsync(Env.Wait)).IsSuccess);Assert.IsFalse((await e.Service.RecoverPendingAsync(Env.Wait)).IsSuccess);Env.Check(facts.Acknowledge(other.AttemptId));
        Assert.IsTrue((await e.Service.RecoverPendingAsync(Env.Wait)).Value.Granted);Env.Check(await e.Ads.RetryFinalizationAsync(Env.Cleanup,Env.Wait));Assert.AreEqual(5,e.Store.Snapshot.Coins);Assert.AreEqual(1,e.Attempt.ShowCount);Assert.AreEqual(0,e.Ads.ReadDiagnostics().FailedCleanup);
    });
    [UnityTest] public IEnumerator DuplicateRecoveryDoesNotWriteAgain()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();await e.Capture().WaitAsync(Env.Wait);var before=e.Storage.Writes;Assert.IsFalse((await e.Service.RecoverPendingAsync(Env.Wait)).IsSuccess);Assert.AreEqual(before,e.Storage.Writes);Assert.AreEqual(5,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator WrongOwnerFactCannotGrantCurrentClaim()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);var c=e.Store.Snapshot.Pending;var other=new ClaimOwnerSnapshot(c.Owner.Mode,"other",c.Owner.SessionGeneration,c.Owner.StorageNamespace);Assert.IsFalse(e.Service.Record(Receipt(c,owner:other)).IsSuccess);Assert.AreEqual(0,e.Facts.PendingCount);e.Attempt.CompleteShow();Assert.IsTrue((await t).Value.Granted);});
    [UnityTest] public IEnumerator WrongAttemptFactCannotGrantCurrentClaim()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);Assert.IsFalse(e.Service.Record(Receipt(e.Store.Snapshot.Pending,attempt:"other")).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);e.Attempt.CompleteShow();await t;});
    [UnityTest] public IEnumerator WrongExecutionModeFactCannotBeUpgradedToNative()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);Assert.IsFalse(e.Service.Record(Receipt(e.Store.Snapshot.Pending,mode:PlatformExecutionMode.Native)).IsSuccess);e.Attempt.CompleteShow();await t;Assert.AreEqual(5,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator OriginalOwnerFactCommitsAfterAuthoritySwitch()=>UniTask.ToCoroutine(async()=>{var e=New(switchOwner:true);e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var original=e.SwitchOwner.CurrentOwner.Value;var op=e.Capture();var t=op.WaitAsync(Env.Wait);e.SwitchOwner.CurrentOwner=new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,"installation-B",2,"local.b");await Env.Frames();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);e.Attempt.CompleteShow();await Env.Frames(10);Assert.AreEqual(Env.OwnerId,e.ReadRaw().OwnerId);Assert.IsTrue(e.ReadRaw().Claims.Single().Owner.SameAs(original));Assert.AreEqual(5,e.ReadRaw().Coins);Assert.IsFalse(e.Service.CaptureRevive().IsSuccess);});
    [UnityTest] public IEnumerator ActualGrantRemainsHiddenUntilCommitReceipt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);e.Storage.HoldNext=true;e.Attempt.CompleteShow();await Env.Frames();Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.IsNotNull(e.Store.Snapshot.Pending);Assert.AreEqual(UniTaskStatus.Pending,t.Status);e.Storage.Release();Assert.IsTrue((await t).Value.Granted);Assert.AreEqual(5,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator ConcurrentBusinessCommandsCannotMutateActiveIntent()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);Assert.IsFalse((await e.Service.BeginRunAsync(2,Env.Wait)).IsSuccess);Assert.IsFalse((await e.Service.CollectAsync(10,Env.Wait)).IsSuccess);Assert.IsFalse((await e.Service.AbandonPendingAsync(Env.Wait)).IsSuccess);e.Attempt.CompleteShow();await t;});
    [UnityTest] public IEnumerator NormalCollectIsSinglePerRunAndDurablyProjected()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Env.Check(await e.Service.BeginRunAsync(2,Env.Wait));Env.Check(await e.Service.CollectAsync(25,Env.Wait));Assert.IsFalse((await e.Service.CollectAsync(25,Env.Wait)).IsSuccess);Assert.AreEqual(25,e.ReadRaw().Coins);Assert.IsTrue(e.ReadRaw().Collected);Assert.AreEqual(2,e.ReadRaw().HighestCollectedLevel);});
    [UnityTest] public IEnumerator ColdOperationCapacityRecoversAfterCanceledWait()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var ops=new List<IReviveOperation>();for(var i=0;i<8;i++)ops.Add(e.Capture());Assert.AreEqual(ErrorKind.Unavailable,e.Service.CaptureRevive().Error.Kind);await ops[0].WaitAsync(default);Assert.IsTrue(e.Service.CaptureRevive().IsSuccess);});
    [UnityTest] public IEnumerator CapturedOperationRechecksRunIdentity()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();var old=e.Capture();await e.FailedRun();Assert.IsFalse((await old.WaitAsync(Env.Wait)).IsSuccess);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator ClaimHistoryBoundNeverEvictsGrantedTombstones()=>UniTask.ToCoroutine(async()=>{var e=New();var owner=new ClaimOwnerSnapshot(ClaimOwnerMode.LocalOnly,Env.OwnerId,1,Env.Ns);var history=Enumerable.Range(0,64).Select(i=>new ReviveClaim("c"+i,"a"+i,"r"+i,owner,1,5,PlatformExecutionMode.Mock,ReviveClaimState.Granted,1));e.Seed(new ReviveSnapshot(owner.Mode,owner.OwnerId,owner.StorageNamespace,1,320,"current",1,ReviveRunPhase.Failed,claims:history));await e.Start();Assert.IsFalse(e.Service.CanRevive);Assert.IsFalse(e.Service.CaptureRevive().IsSuccess);Assert.AreEqual(64,e.Store.Snapshot.Claims.Count);});
