    [UnityTest] public IEnumerator ContextCloseWaitsVisibleAdAndPersistsItsCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();var t=e.Capture().WaitAsync(Env.Wait);var close=e.Context.CloseAsync(Env.Wait);await Env.Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Attempt.CompleteShow();Env.Check(await close);Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(5,e.ReadRaw().Coins);Assert.AreEqual(0,e.Context.RetainedModuleCount);});
    [UnityTest] public IEnumerator CloseWaitsPendingIntentWriteWithoutStartingAd()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();e.Storage.HoldNext=true;var t=e.Capture().WaitAsync(Env.Wait);var close=e.Context.CloseAsync(Env.Wait);await Env.Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);e.Storage.Release();Env.Check(await close);Assert.AreEqual(0,e.Backend.Attempts.Count);Assert.AreEqual(0,e.ReadRaw().Coins);Assert.IsNull(e.ReadRaw().Pending);await t;});
    [UnityTest] public IEnumerator CloseTimeoutDoesNotReleaseActualWrite()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.FailedRun();e.Storage.HoldNext=true;var t=e.Capture().WaitAsync(Env.Wait);Assert.AreEqual(ErrorKind.Timeout,(await e.Context.CloseAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);Assert.Greater(e.Context.RetainedModuleCount,0);e.Storage.Release();Env.Check(await e.Context.CloseAsync(Env.Wait));await t;});
    [UnityTest] public IEnumerator StorageCleanupFailureRequiresExplicitRetryOnly()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Storage.FailCleanup=true;Assert.IsFalse((await e.Context.CloseAsync(Env.Wait)).IsSuccess);var attempts=e.Storage.Cleanups;Assert.IsFalse((await e.Context.CloseAsync(Env.Wait)).IsSuccess);Assert.AreEqual(attempts,e.Storage.Cleanups);e.Storage.FailCleanup=false;Env.Check(await e.Context.RetryCleanupAsync(Env.Cleanup,Env.Wait));Assert.AreEqual(attempts+1,e.Storage.Cleanups);});
    [UnityTest] public IEnumerator AdsCleanupFailureDoesNotReplayGrantedRewardOnRetry()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.FailCleanup=true;await e.Start();await e.FailedRun();var r=await e.Capture().WaitAsync(Env.Wait);Assert.IsTrue(r.IsSuccess&&r.Value.Granted);Assert.IsFalse((await e.Context.CloseAsync(Env.Wait)).IsSuccess);e.Backend.FailCleanup=false;Env.Check(await e.Context.RetryCleanupAsync(Env.Cleanup,Env.Wait));Assert.AreEqual(5,e.ReadRaw().Coins);Assert.AreEqual(1,e.Attempt.ShowCount);});
    [UnityTest] public IEnumerator RejectedMutationNeverPublishesLiveCoins()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Env.Check(await e.Service.BeginRunAsync(1,Env.Wait));e.Disk.Faults.Enqueue(FakeStorageFault.Reject);Assert.IsFalse((await e.Service.CollectAsync(10,Env.Wait)).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);Assert.IsFalse(e.Store.Snapshot.Collected);Env.Check(await e.Service.CollectAsync(10,Env.Wait));Assert.AreEqual(10,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator CanceledMutationStillPublishesOnlyActualCommittedSnapshot()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Env.Check(await e.Service.BeginRunAsync(1,Env.Wait));e.Storage.HoldNext=true;using(var c=new CancellationTokenSource()){var t=e.Service.CollectAsync(10,OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(0,e.Store.Snapshot.Coins);e.Storage.Release();await Env.Frames();Assert.AreEqual(10,e.Store.Snapshot.Coins);Assert.IsTrue(e.Store.Snapshot.Collected);}});
    [UnityTest] public IEnumerator AbortedClaimCannotBeUpgradedByLateForgedCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.Skip=true;await e.Start();await e.FailedRun();await e.Capture().WaitAsync(Env.Wait);var c=e.Store.Snapshot.Claims.Single();Assert.IsFalse(e.Service.Record(Receipt(c)).IsSuccess);Assert.AreEqual(0,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator UnknownClaimFactIsRejectedWithoutSideEffects()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var owner=e.Owner.CurrentOwner.Value;var c=new ReviveClaim("unknown","a","r",owner,1,5,PlatformExecutionMode.Mock,ReviveClaimState.Pending);Assert.IsFalse(e.Service.Record(Receipt(c)).IsSuccess);Assert.AreEqual(0,e.Facts.PendingCount);Assert.AreEqual(0,e.Store.Snapshot.Coins);});
    [UnityTest] public IEnumerator InvalidRunAndRewardInputsNeverWrite()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var writes=e.Storage.Writes;Assert.IsFalse((await e.Service.BeginRunAsync(0,Env.Wait)).IsSuccess);Assert.AreEqual(writes,e.Storage.Writes);Env.Check(await e.Service.BeginRunAsync(1,Env.Wait));writes=e.Storage.Writes;Assert.IsFalse((await e.Service.CollectAsync(0,Env.Wait)).IsSuccess);Assert.AreEqual(writes,e.Storage.Writes);});
    [UnityTest] public IEnumerator TimeScaleZeroStillDrainsAndCommitsLateFact()=>UniTask.ToCoroutine(async()=>{var e=New();e.Backend.HoldShow=true;await e.Start();await e.FailedRun();Time.timeScale=0;var t=e.Capture().WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)));Assert.AreEqual(ErrorKind.Timeout,(await t).Error.Kind);e.Attempt.CompleteShow();await Env.Frames(10);Assert.AreEqual(5,e.Store.Snapshot.Coins);Assert.IsFalse(e.Service.Busy);});
    [UnityTest] public IEnumerator FailedGenerationReserveNeverPublishesOwner()=>UniTask.ToCoroutine(async()=>{var e=New();e.Disk.Faults.Enqueue(FakeStorageFault.Reject);Assert.IsFalse((await e.Context.StartAsync(Env.Wait)).IsSuccess);Assert.IsNull(e.Owner.CurrentOwner);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator GenerationExhaustionDoesNotWrapOrStartAds()=>UniTask.ToCoroutine(async()=>{var e=New();e.Seed(new ReviveSnapshot(ClaimOwnerMode.LocalOnly,Env.OwnerId,Env.Ns,long.MaxValue));Assert.IsFalse((await e.Context.StartAsync(Env.Wait)).IsSuccess);Assert.IsNull(e.Owner.CurrentOwner);Assert.AreEqual(0,e.Backend.Attempts.Count);});
    [UnityTest] public IEnumerator FakeAccountSwitchLateGrantWritesOnlyOriginalAccountStore()=>UniTask.ToCoroutine(async()=>
    {
        var identity=new MiniFramework.Providers.IdentityFake.FakeIdentityProvider();var policy=MiniFramework.Ownership.OwnershipPolicy.AccountScoped(true);var ns=policy.NamespaceFor(new BusinessIdentity(identity.Id,"account-A",IdentityMode.Simulated)).Value;
        var disk=new FakeStorageStore();var provider=new FakeStorageProvider(disk);var address=new StorageAddress(ns,"main");var store=new Game.Revive.ReviveRepository(provider,ClaimOwnerMode.AccountScoped,"account-A",address);var owner=new LoginOwner(identity,store.Id);
        var backend=new MiniFramework.Providers.AdsMock.MockRewardedAdBackend{HoldShow=true};var facts=new AdReceiptJournal();var service=new Game.Revive.ReviveService(store,facts);var ads=new MiniFramework.Ads.AdsService(backend,service,ownerModuleId:owner.Id);var platform=new MiniFramework.Platform.PlatformService(new MiniFramework.Providers.PlatformMock.MockPlatformBackend{Startup=new PlatformStartup(new PlatformCapabilities(new[]{new PlatformCapability(PlatformFeature.Lifecycle,CapabilitySupport.Supported,CapabilityAvailability.Available,"test.life"),new PlatformCapability(PlatformFeature.RewardedAds,CapabilitySupport.Supported,CapabilityAvailability.Available,"test.ads",CapabilityConstraints.ForegroundOnly,1)}),PlatformVisibility.Foreground)});
        Func<IModule,Type[],MiniFramework.Runtime.ModuleRegistration> reg=(m,t)=>new MiniFramework.Runtime.ModuleRegistration(m.Id,m.Dependencies,()=>m,t);
        var ctx=new MiniFramework.Runtime.GameContext(new[]{reg(store,new[]{typeof(IRevivePersistenceView)}),reg(owner,new[]{typeof(IClaimOwnerAuthority)}),reg(platform,new[]{typeof(IPlatformCapabilities),typeof(IPlatformLifecycle)}),reg(ads,new[]{typeof(IAdsService)}),reg(service,new[]{typeof(IReviveService)})},Env.Cleanup);
        try
        {
            Env.Check(await ctx.StartAsync(Env.Wait));var original=owner.CurrentOwner.Value;Env.Check(await service.BeginRunAsync(1,Env.Wait));Env.Check(await service.FailRunAsync(Env.Wait));var op=service.CaptureRevive().Value;var task=op.WaitAsync(Env.Wait);
            identity.NextOwnerId="account-B";var changed=await owner.Inner.CaptureSwitch().Value.WaitAsync(Env.Wait);Assert.IsTrue(changed.IsSuccess);await Env.Frames();Assert.AreEqual(ErrorKind.Canceled,(await task).Error.Kind);
            backend.Attempts[0].CompleteShow();await Env.Frames(10);var raw=StorageFormat.Decode(disk.CopyRaw(address),new StorageLimits()).Value;var ledger=Game.Revive.ReviveCodec.Decode(raw.Records[0].CopyPayload()).Value;
            Assert.AreEqual(5,ledger.Coins);Assert.IsTrue(ledger.Claims.Single().Owner.SameAs(original));Assert.AreEqual("account-A",ledger.OwnerId);Assert.IsNull(disk.CopyRaw(new StorageAddress(changed.Value.Owner.StorageNamespace,"main")));Assert.IsFalse(service.CaptureRevive().IsSuccess);
        }
        finally{foreach(var a in backend.Attempts){a.CompleteLoad();a.CompleteShow();}var closed=await ctx.CloseAsync(Env.Wait);if(!closed.IsSuccess)closed=await ctx.RetryCleanupAsync(Env.Cleanup,Env.Wait);Env.Check(closed);}
    });

